.btn {
  padding: 14px 22px;
  border: none;
  border-radius: 10px;
  color: #fff;
  background: linear-gradient(135deg, #6366f1, #ec4899);
  box-shadow: 0 1px 2px rgba(0,0,0,0.2), 0 8px 18px rgba(0,0,0,0.25);
  cursor: pointer;
}
.btn:active {
  box-shadow: inset 0 3px 8px rgba(0,0,0,0.35);
}
